test('upcoming reminder uses canonical experience profiles and privacy-safe preparation copy',()=>{const learning=preparationProfileFromKey('etna-learning','en');const live=preparationProfileFromKey('etna-live','en');yes(learning&&live&&JSON.stringify(learning)!==JSON.stringify(live),'canonical experiences do not produce different guidance');yes(preparationProfileFromKey('customer-supplied-text','en')===null,'arbitrary profile input was accepted');const fallback=preparationReminder('unknown');yes(fallback.destinationUrl===preparationDestination('unknown')&&fallback.destinationUrl==='/install?preparation=standard-etna','safe fallback destination changed');const reminderText=JSON.stringify([preparationReminder('etna-premium'),preparationReminder('etna-learning'),preparationReminder('etna-live'),preparationReminder('etna-stories'),fallback]);for(const forbidden of ['customer_name','customer_email','customer_phone','booking_id','booking_code','gift_card','ownership_id','tomorrow','domani'])no(reminderText.toLowerCase().includes(forbidden),`reminder copy exposes or overclaims ${forbidden}`);yes(api.includes("select: 'id,status,lead_status,experience_id,requested_date")&&api.includes("select: 'id,date,start_time,experience_id"),'preparation profile is not derived from authoritative experience_id');yes(api.includes('preparationReminder(authoritative.preparationExperienceId)'),'scheduled reminder does not use the profile resolver');yes(api.includes("cleanDestination(config.destinationUrl, '/install')"),'owned destination is not constrained by the internal URL guard');for(const field of ['customer_name','customer_email','customer_phone','message','booking_code'])no(preparationSource.includes(field),`preparation profile depends on customer input: ${field}`);yes(ui.includes('function PreparationGuidance')&&ui.includes('Cosa indossare')&&ui.includes('What to bring'),'rich preparation guidance is not rendered at /install');});
test('reschedules and activity changes supersede old reminders while cancellation prevents replacement',()=>{yes(api.includes("['booking_rescheduled','booking_cancelled','operational_change'].includes(eventType)")&&api.includes("terminal_reason='superseded'")&&api.includes('superseded_by_${eventType}'),'supersession audit missing');yes(api.includes("category='customer_upcoming_reminder' AND status='scheduled'"),'old reminder cancellation missing');yes(api.includes("['booking_confirmed','booking_rescheduled','operational_change'].includes(eventType)&&activityAvailable"),'eligible fixed-excursion changes do not schedule a replacement');yes(api.includes("String(authoritative.fixedExcursion.status||'').toLowerCase()!=='cancelled'")&&api.includes('authoritative.fixedExcursion.active!==false'),'cancelled/inactive excursion can receive a replacement reminder');no(api.includes("['booking_confirmed','booking_rescheduled','booking_cancelled'"),'booking cancellation entered reminder scheduling');});
test('typed ownership preferences remain separate from public campaign consent',()=>{for(const token of ['status_updates_enabled','operational_updates_enabled','reminders_enabled','review_reminders_enabled','push_enabled','inapp_enabled'])yes(d1Operations.includes(token),`typed preference missing ${token}`);yes(api.includes('ownership_preferences_required')&&ui.includes('updateNotificationOwnershipPreferences'),'owned preference API/UI missing');no(d1Operations.includes('promotions'),'marketing preference leaked into ownership model');});
test('delivery retries are bounded, auditable, and prevent uncertain push replay',()=>{for(const token of ['max_attempts INTEGER NOT NULL DEFAULT 3','notification_delivery_attempts','push_started_at','push_delivered_at','dead_subscription_at'])yes(d1Operations.includes(token),`delivery state missing ${token}`);yes(worker.includes("push_outcome_unknown")&&worker.includes("if(job.push_started_at)")&&worker.includes("status='scheduled',next_attempt_at=?")&&worker.includes('attempt<maxAttempts'),'at-most-once/backoff contract missing');yes(worker.includes("push.dead")&&worker.includes("dead_subscription"),'dead endpoint terminal handling missing');});
test('Pages and Worker record push-service acceptance without claiming client delivery',()=>{for(const source of [api,worker]){yes(source.includes('push_service_accepted'),'push-service acceptance code missing');yes(source.includes('deliveryConfirmed:false')||source.includes('deliveryConfirmed: false'),'delivery confirmation remains ambiguous');yes(source.includes('push.accepted'),'transport acceptance is not authoritative');}yes(api.includes('recordPushAttempt(database,event.job_id,attemptNumber,push)'),'immediate Pages delivery attempt is not recorded');yes(api.includes('push_started_at,push_delivered_at,dead_subscription_at'),'Admin job observability omits push state');yes(worker.includes("'push','sent',?,'push_service_accepted'"),'Worker acceptance attempt lacks safe classification');yes(ui.includes('Accepted by push service')&&ui.includes('accepted by push service'),'Admin labels do not expose acceptance semantics');no(ui.includes('Successful sends')||ui.includes('Test notification sent.'),'UI still claims browser delivery');for(const token of ['RFC 8291-encrypted','accepted for delivery','There is no client delivery receipt','represent push-service acceptance'])yes(ownershipDoc.includes(token),`delivery semantics documentation missing: ${token}`);});
test('Pages and Worker pass only resolved safe public presentation metadata',()=>{for(const source of [api,worker]){yes(source.includes('const notification'),'push presentation object missing');yes(source.includes('notification })')||source.includes('notification});')||source.includes(',notification})'),'presentation object is not passed to Web Push');yes(source.includes('destination_url'),'safe destination source missing');}yes(api.includes('{ category: event.category, title, body: bodyText, url: event.destination_url }'),'Pages does not pass resolved localized presentation');yes(worker.includes('{category:event.category,title,body,url:event.destination_url}')&&worker.includes('{category:job.category,title,body,url:job.destination_url}'),'Worker does not pass broadcast and owned-job presentation');const apiPushCalls=[...api.matchAll(/sendWebPush\([^;]+/g)].map((match)=>match[0]).join('\n');const workerPushCalls=[...worker.matchAll(/sendWebPush\([^;]+/g)].map((match)=>match[0]).join('\n');for(const calls of [apiPushCalls,workerPushCalls]){for(const forbidden of ['entity_id','entity_ref','ownership_id','subscription_id','device_id','claim','token'])no(calls.includes(forbidden),`private identifier entered push presentation: ${forbidden}`);}yes(api.includes("category: 'customer_booking_confirmed'")&&api.includes("titleEn: 'Booking confirmed'")&&api.includes("bodyEn: 'Your vulcanIQ booking has been confirmed.'"),'booking-confirmed safe copy changed');});
test('insecure recovery and second-device alternatives remain unavailable',()=>{const ownershipRoute=api.slice(api.indexOf("if (route === 'ownership')"),api.indexOf("if(route==='personalized-events'"));for(const forbidden of ['recovery','second-device','customer_email','customer_phone','booking_code'])no(ownershipRoute.includes(forbidden),`insecure ownership alternative exposed: ${forbidden}`);no(/manual.*ownership|issue.*ownership.*admin/i.test(api+ui),'Admin raw enrollment issuance was added without trusted delivery');});
test('customer journey publication reconciles durable outbox rather than posting browser assertions',()=>{yes(service.includes("'personalized-events/reconcile'")&&bookingService.includes('reconcileOwnedBookingEvents'),'outbox reconciliation client missing');no(service.includes("entityType: 'booking_request', entityId, eventType"),'browser still publishes asserted business event');yes(main.includes('await publishCustomerNotificationEvent().catch(() => null)'),'canonical mutation reconciliation hook missing');});
test('notification backend supports Secret key primary without opaque bearer misuse or auth override',()=>{const secret=resolveSupabaseBackendCredential({SUPABASE_SECRET_KEY:'sb_secret_notification_regression',SUPABASE_SERVICE_ROLE_KEY:'legacy.header.signature'});const secretHeaders=supabaseBackendHeaders(secret);yes(secret.source==='SUPABASE_SECRET_KEY'&&secretHeaders.apikey===secret.key,'Secret key is not preferred');no('Authorization' in secretHeaders,'opaque Secret key became bearer JWT');let overrideBlocked=false;try{supabaseBackendHeaders(secret,{headers:{Authorization:'Bearer attacker.jwt'}});}catch(error){overrideBlocked=error.message==='supabase_auth_header_override_forbidden';}yes(overrideBlocked,'caller-provided Authorization override was accepted');const legacy=resolveSupabaseBackendCredential({SUPABASE_SERVICE_ROLE_KEY:'legacy.header.signature'});yes(supabaseBackendHeaders(legacy).Authorization==='Bearer legacy.header.signature','legacy rollback bearer missing');yes(worker.includes('resolveSupabaseBackendCredential(env)')&&worker.includes('supabaseBackendHeaders(backendCredential'),'Worker does not use shared backend credential contract');yes(api.includes('Authorization: `Bearer ${token}`'),'Admin user JWT bearer flow changed');});
test('Preview Worker is isolated while default Production identity remains unchanged',()=>{const preview=workerConfig.slice(workerConfig.indexOf('[env.preview]'));const defaults=workerConfig.slice(0,workerConfig.indexOf('[env.preview]'));const defaultName=defaults.match(/^name\s*=\s*"([^"]+)"/m)?.[1];const previewName=preview.match(/^name\s*=\s*"([^"]+)"/m)?.[1];const defaultDatabaseId=defaults.match(/^database_id\s*=\s*"([^"]+)"/m)?.[1];const previewDatabaseId=preview.match(/^database_id\s*=\s*"([^"]+)"/m)?.[1];eq(defaultName,'vulcaniq-notifications','Production Worker name changed');eq(defaultDatabaseId,'1edcda8a-3faf-4c6c-8c89-a46d424cd844','Production D1 ID changed');no(/^preview_database_id\s*=/m.test(defaults),'Production config contains forbidden preview_database_id');eq(previewName,'vulcaniq-notifications-preview','Preview Worker name changed');eq(previewDatabaseId,'8e220c75-2060-4cb9-954e-073a422d5f34','Preview D1 ID changed');yes(defaultDatabaseId!==previewDatabaseId,'Production and Preview D1 IDs must differ');for(const token of ['database_name = "vulcaniq-notifications"'])yes(defaults.includes(token),`Production default changed: ${token}`);for(const token of ['database_name = "vulcaniq-notifications-preview"'])yes(preview.includes(token),`Preview config missing ${token}`);const keys=(block)=>[...block.matchAll(/^([A-Z][A-Z0-9_]*)\s*=/gm)].map((match)=>match[1]).sort().join(',');eq(keys(defaults.slice(defaults.indexOf('[vars]'))),keys(preview.slice(preview.indexOf('[env.preview.vars]'))),'Preview non-secret variables differ from defaults');});
test('notification Cron remains disabled in default and Preview environments',()=>{eq((workerConfig.match(/crons\s*=\s*\[\]/g)||[]).length,2,'both empty Cron declarations are required');yes(/\[triggers\]\s*\r?\ncrons\s*=\s*\[\]/.test(workerConfig),'default notification Cron was enabled');yes(/\[env\.preview\.triggers\]\s*\r?\ncrons\s*=\s*\[\]/.test(workerConfig),'Preview notification Cron was enabled');});
test('campaign failures are returned and visible to privileged Admin',()=>{yes(api.includes('failure_reason FROM notification_campaigns'),'failure reason missing from authorized campaign response');yes(ui.includes('item.failure_reason')&&ui.includes('item.status} · ${item.failure_reason}'),'failure reason missing from Admin status UI');});
test('notification titles use concise canonical branding',()=>{no(/VulcanIQ notification test|Problema operativo VulcanIQ|VulcanIQ operational issue/.test(api),'duplicate legacy branding remains');yes(api.includes('vulcanIQ notification test'),'canonical test title missing');yes(worker.includes("title_it:'Aggiornamento Etna'")&&worker.includes("title_en:'Etna update'"),'concise Etna titles missing');});
